-- Add missing columns to webhook_events for full idempotency tracking
-- These columns enable: payload storage for debugging, error tracking, and completion timestamps

-- Add payload column for storing full event data for debugging
ALTER TABLE public.webhook_events
  ADD COLUMN IF NOT EXISTS payload JSONB;

-- Add error_message column for tracking failure details
ALTER TABLE public.webhook_events
  ADD COLUMN IF NOT EXISTS error_message TEXT;

-- Add completed_at column for tracking when processing finished
ALTER TABLE public.webhook_events
  ADD COLUMN IF NOT EXISTS completed_at TIMESTAMPTZ;

-- Add constraint to ensure status values are valid
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint WHERE conname = 'webhook_events_status_check'
  ) THEN
    ALTER TABLE public.webhook_events
      ADD CONSTRAINT webhook_events_status_check
      CHECK (status IN ('processing', 'completed', 'failed'));
  END IF;
END $$;

-- Update the mark_webhook_event_failed function to store error message
CREATE OR REPLACE FUNCTION mark_webhook_event_failed(p_event_id TEXT, p_error_message TEXT DEFAULT NULL)
RETURNS VOID AS $$
BEGIN
  UPDATE webhook_events
  SET
    status = 'failed',
    error_message = p_error_message,
    completed_at = now()
  WHERE event_id = p_event_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Update mark_webhook_event_completed to set completed_at
CREATE OR REPLACE FUNCTION mark_webhook_event_completed(p_event_id TEXT)
RETURNS VOID AS $$
BEGIN
  UPDATE webhook_events
  SET
    status = 'completed',
    completed_at = now()
  WHERE event_id = p_event_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Create function to claim a webhook event (returns true if successfully claimed)
CREATE OR REPLACE FUNCTION claim_webhook_event(
  p_event_id TEXT,
  p_event_type TEXT,
  p_payload JSONB DEFAULT NULL
)
RETURNS TABLE(is_new BOOLEAN, existing_status TEXT) AS $$
DECLARE
  v_existing_status TEXT;
BEGIN
  -- First check if event exists
  SELECT we.status INTO v_existing_status
  FROM webhook_events we
  WHERE we.event_id = p_event_id;

  IF v_existing_status IS NOT NULL THEN
    -- Event already exists
    RETURN QUERY SELECT false, v_existing_status;
    RETURN;
  END IF;

  -- Try to insert new event
  BEGIN
    INSERT INTO webhook_events (event_id, event_type, status, payload)
    VALUES (p_event_id, p_event_type, 'processing', p_payload);

    RETURN QUERY SELECT true, NULL::TEXT;
  EXCEPTION WHEN unique_violation THEN
    -- Concurrent insert won - get the status of that insert
    SELECT we.status INTO v_existing_status
    FROM webhook_events we
    WHERE we.event_id = p_event_id;

    RETURN QUERY SELECT false, v_existing_status;
  END;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Add comments for documentation
COMMENT ON COLUMN public.webhook_events.payload IS 'Full Stripe event payload for debugging';
COMMENT ON COLUMN public.webhook_events.error_message IS 'Error details if processing failed';
COMMENT ON COLUMN public.webhook_events.completed_at IS 'Timestamp when processing finished (success or failure)';
COMMENT ON FUNCTION claim_webhook_event IS 'Atomically claims a webhook event for processing. Returns is_new=true if claimed, false if already exists.';


-- ========================================
-- Migration: 20250203000000_fix_admin_policy_recursion.sql
-- ========================================

-- Fix infinite recursion in admin RLS policies
-- Migration: 20250203_fix_admin_policy_recursion.sql
-- Description: Uses SECURITY DEFINER function to check admin role without RLS recursion

-- Create a SECURITY DEFINER function to check if user is admin
-- This bypasses RLS to avoid infinite recursion
CREATE OR REPLACE FUNCTION public.is_admin(user_id UUID)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = public
STABLE
AS $$
  SELECT EXISTS (
    SELECT 1 FROM profiles
    WHERE id = user_id AND role = 'admin'
  );
$$;

-- Grant execute permission
GRANT EXECUTE ON FUNCTION public.is_admin(UUID) TO authenticated;

-- Drop the recursive policies
DROP POLICY IF EXISTS "Users can view own profile or admins can view all" ON public.profiles;
DROP POLICY IF EXISTS "Users can update own profile or admins can update all" ON public.profiles;

-- Recreate profiles policies using the SECURITY DEFINER function
CREATE POLICY "Users can view own profile or admins can view all"
ON public.profiles FOR SELECT
TO authenticated
USING (
    auth.uid() = id
    OR public.is_admin(auth.uid())
);

CREATE POLICY "Users can update own profile or admins can update all"
ON public.profiles FOR UPDATE
TO authenticated
USING (
    auth.uid() = id
    OR public.is_admin(auth.uid())
);

-- Fix subscriptions policies (drop and recreate)
DROP POLICY IF EXISTS "Admins can view all subscriptions" ON public.subscriptions;
DROP POLICY IF EXISTS "Admins can update all subscriptions" ON public.subscriptions;

CREATE POLICY "Admins can view all subscriptions"
ON public.subscriptions FOR SELECT
TO authenticated
USING (
    user_id = auth.uid()
    OR public.is_admin(auth.uid())
);

CREATE POLICY "Admins can update all subscriptions"
ON public.subscriptions FOR UPDATE
TO authenticated
USING (
    public.is_admin(auth.uid())
);

-- Fix credit_transactions policies (drop and recreate)
DROP POLICY IF EXISTS "Admins can view all credit transactions" ON public.credit_transactions;
DROP POLICY IF EXISTS "Admins can insert credit transactions" ON public.credit_transactions;

CREATE POLICY "Admins can view all credit transactions"
ON public.credit_transactions FOR SELECT
TO authenticated
USING (
    user_id = auth.uid()
    OR public.is_admin(auth.uid())
);

CREATE POLICY "Admins can insert credit transactions"
ON public.credit_transactions FOR INSERT
TO authenticated
WITH CHECK (
    user_id = auth.uid()
    OR public.is_admin(auth.uid())
);


-- ========================================
-- Migration: 20250221000000_secure_credits.sql
-- ========================================

-- ============================================================================
-- Migration: Secure Credits System
-- ============================================================================
-- This migration locks down the credit system to prevent unauthorized
-- credit manipulation and free AI generation exploits.
--
-- Changes:
-- 1. Revokes EXECUTE permission on credit-modifying RPCs from authenticated users
-- 2. Creates a trigger to prevent direct updates to credits_balance column
-- 3. Updates RPC functions to use a trusted session flag
-- ============================================================================

-- 1. Revoke access to sensitive RPCs from authenticated users
-- These functions should only be called by the service_role (backend)
REVOKE EXECUTE ON FUNCTION public.increment_credits(UUID, INTEGER) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.decrement_credits(UUID, INTEGER) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.increment_credits_with_log(UUID, INTEGER, TEXT, TEXT, TEXT) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.decrement_credits_with_log(UUID, INTEGER, TEXT, TEXT, TEXT) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.refund_credits(UUID, INTEGER, TEXT) FROM authenticated;

-- 2. Update RPC functions to set trusted operation flag
-- This allows the trigger to distinguish between direct user updates and RPC calls

-- Update increment_credits_with_log to set trusted flag
CREATE OR REPLACE FUNCTION public.increment_credits_with_log(
  target_user_id UUID,
  amount INTEGER,
  transaction_type TEXT DEFAULT 'purchase',
  ref_id TEXT DEFAULT NULL,
  description TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  new_balance INTEGER;
BEGIN
  -- Set trusted operation flag
  PERFORM set_config('app.trusted_credit_operation', 'true', true);

  -- Increment credits
  UPDATE public.profiles
  SET credits_balance = credits_balance + amount
  WHERE id = target_user_id
  RETURNING credits_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'User not found: %', target_user_id;
  END IF;

  -- Log transaction
  INSERT INTO public.credit_transactions (user_id, amount, type, reference_id, description)
  VALUES (target_user_id, amount, transaction_type, ref_id, description);

  RETURN new_balance;
END;
$$;

-- Update decrement_credits_with_log to set trusted flag
CREATE OR REPLACE FUNCTION public.decrement_credits_with_log(
  target_user_id UUID,
  amount INTEGER,
  transaction_type TEXT DEFAULT 'usage',
  ref_id TEXT DEFAULT NULL,
  description TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  current_balance INTEGER;
  new_balance INTEGER;
BEGIN
  -- Set trusted operation flag
  PERFORM set_config('app.trusted_credit_operation', 'true', true);

  -- Lock row and check balance
  SELECT credits_balance INTO current_balance
  FROM public.profiles
  WHERE id = target_user_id
  FOR UPDATE;

  IF current_balance IS NULL THEN
    RAISE EXCEPTION 'User not found: %', target_user_id;
  END IF;

  IF current_balance < amount THEN
    RAISE EXCEPTION 'Insufficient credits. Required: %, Available: %', amount, current_balance;
  END IF;

  -- Decrement credits
  UPDATE public.profiles
  SET credits_balance = credits_balance - amount
  WHERE id = target_user_id
  RETURNING credits_balance INTO new_balance;

  -- Log transaction (negative amount for deduction)
  INSERT INTO public.credit_transactions (user_id, amount, type, reference_id, description)
  VALUES (target_user_id, -amount, transaction_type, ref_id, description);

  RETURN new_balance;
END;
$$;

-- Update refund_credits
CREATE OR REPLACE FUNCTION public.refund_credits(
  target_user_id UUID,
  amount INTEGER,
  job_id TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN public.increment_credits_with_log(
    target_user_id,
    amount,
    'refund',
    job_id,
    'Processing refund'
  );
END;
$$;

-- Update the simple increment/decrement functions
CREATE OR REPLACE FUNCTION public.increment_credits(target_user_id UUID, amount INTEGER)
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  -- Set trusted operation flag
  PERFORM set_config('app.trusted_credit_operation', 'true', true);

  UPDATE public.profiles
  SET credits_balance = credits_balance + amount
  WHERE id = target_user_id;
END;
$$;

CREATE OR REPLACE FUNCTION public.decrement_credits(target_user_id UUID, amount INTEGER)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  current_balance INTEGER;
  new_balance INTEGER;
BEGIN
  -- Set trusted operation flag
  PERFORM set_config('app.trusted_credit_operation', 'true', true);

  -- Get current balance
  SELECT credits_balance INTO current_balance
  FROM public.profiles
  WHERE id = target_user_id;

  IF current_balance IS NULL THEN
    RAISE EXCEPTION 'User profile not found';
  END IF;

  IF current_balance < amount THEN
    RAISE EXCEPTION 'Insufficient credits';
  END IF;

  -- Decrement credits
  UPDATE public.profiles
  SET credits_balance = credits_balance - amount
  WHERE id = target_user_id
  RETURNING credits_balance INTO new_balance;

  RETURN new_balance;
END;
$$;

-- 3. Create trigger function to prevent direct updates to credits_balance
CREATE OR REPLACE FUNCTION public.prevent_credit_update()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  -- Check if this is a trusted internal operation (from our RPC functions)
  IF current_setting('app.trusted_credit_operation', true) = 'true' THEN
    RETURN NEW;
  END IF;

  -- Block any attempt to change credits_balance for untrusted operations
  IF NEW.credits_balance IS DISTINCT FROM OLD.credits_balance THEN
    RAISE EXCEPTION 'Cannot update credits_balance directly. Use the designated API endpoints.';
  END IF;

  RETURN NEW;
END;
$$;

-- 4. Create the trigger on profiles table
DROP TRIGGER IF EXISTS protect_credits_balance ON public.profiles;
CREATE TRIGGER protect_credits_balance
BEFORE UPDATE ON public.profiles
FOR EACH ROW
EXECUTE FUNCTION public.prevent_credit_update();

-- 5. Add comments to document the security measures
COMMENT ON FUNCTION public.prevent_credit_update() IS
'Security trigger function that prevents direct updates to credits_balance column. Only trusted RPC functions can modify credits.';

COMMENT ON TRIGGER protect_credits_balance ON public.profiles IS
'Prevents users from directly updating their credits_balance. Credits must be modified through server-side API calls using designated RPC functions.';


-- ========================================
-- Migration: 20250302000000_add_sync_tables.sql
-- ========================================

-- ============================================================================
-- Stripe x Database Sync System - Database Schema
-- ============================================================================
-- This migration adds tables and columns needed for scheduled synchronization
-- between Stripe and our database.
--
-- Changes:
-- 1. Create sync_runs table for observability
-- 2. Add retry columns to webhook_events table
-- 3. Add indexes for efficient queries
-- 4. Set up RLS policies
-- ============================================================================

-- ============================================================================
-- Create sync_runs table
-- ============================================================================
-- Tracks execution history of scheduled sync jobs (expiration checks,
-- webhook recovery, full reconciliation)

CREATE TABLE IF NOT EXISTS sync_runs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  job_type TEXT NOT NULL CHECK (job_type IN ('expiration_check', 'webhook_recovery', 'full_reconciliation')),
  started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  status TEXT NOT NULL DEFAULT 'running' CHECK (status IN ('running', 'completed', 'failed')),
  records_processed INTEGER DEFAULT 0,
  records_fixed INTEGER DEFAULT 0,
  discrepancies_found INTEGER DEFAULT 0,
  error_message TEXT,
  metadata JSONB,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

-- Indexes for querying sync history
CREATE INDEX idx_sync_runs_job_type ON sync_runs(job_type);
CREATE INDEX idx_sync_runs_started_at ON sync_runs(started_at DESC);
CREATE INDEX idx_sync_runs_status ON sync_runs(status);

-- ============================================================================
-- Add retry tracking columns to webhook_events
-- ============================================================================
-- These columns enable webhook recovery functionality

ALTER TABLE webhook_events
ADD COLUMN IF NOT EXISTS retry_count INTEGER DEFAULT 0,
ADD COLUMN IF NOT EXISTS last_retry_at TIMESTAMPTZ,
ADD COLUMN IF NOT EXISTS recoverable BOOLEAN DEFAULT TRUE;

-- Index for finding retryable failed events
CREATE INDEX IF NOT EXISTS idx_webhook_events_retryable
ON webhook_events(status, recoverable, retry_count)
WHERE status = 'failed' AND recoverable = TRUE;

-- ============================================================================
-- Row Level Security (RLS) Policies
-- ============================================================================

-- Enable RLS on sync_runs (admin/service role only)
ALTER TABLE sync_runs ENABLE ROW LEVEL SECURITY;

-- Service role can manage sync_runs
CREATE POLICY "Service role can manage sync_runs" ON sync_runs
  FOR ALL
  USING (auth.role() = 'service_role');

-- Grant necessary permissions
GRANT SELECT, INSERT, UPDATE ON sync_runs TO service_role;

-- ============================================================================
-- Helper Functions
-- ============================================================================

-- Function to get recent sync run statistics
CREATE OR REPLACE FUNCTION get_sync_run_stats(
  p_job_type TEXT DEFAULT NULL,
  p_hours INTEGER DEFAULT 24
)
RETURNS TABLE (
  job_type TEXT,
  total_runs BIGINT,
  successful_runs BIGINT,
  failed_runs BIGINT,
  avg_records_processed NUMERIC,
  avg_records_fixed NUMERIC,
  last_run_at TIMESTAMPTZ
) AS $$
BEGIN
  RETURN QUERY
  SELECT
    sr.job_type,
    COUNT(*) as total_runs,
    COUNT(*) FILTER (WHERE sr.status = 'completed') as successful_runs,
    COUNT(*) FILTER (WHERE sr.status = 'failed') as failed_runs,
    AVG(sr.records_processed) as avg_records_processed,
    AVG(sr.records_fixed) as avg_records_fixed,
    MAX(sr.started_at) as last_run_at
  FROM sync_runs sr
  WHERE
    sr.started_at > NOW() - (p_hours || ' hours')::INTERVAL
    AND (p_job_type IS NULL OR sr.job_type = p_job_type)
  GROUP BY sr.job_type
  ORDER BY sr.job_type;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to get failed webhook events ready for retry
CREATE OR REPLACE FUNCTION get_retryable_webhook_events(
  p_limit INTEGER DEFAULT 50
)
RETURNS TABLE (
  id UUID,
  event_id TEXT,
  event_type TEXT,
  retry_count INTEGER,
  last_retry_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ,
  error_message TEXT
) AS $$
BEGIN
  RETURN QUERY
  SELECT
    we.id,
    we.event_id,
    we.event_type,
    we.retry_count,
    we.last_retry_at,
    we.created_at,
    we.error_message
  FROM webhook_events we
  WHERE
    we.status = 'failed'
    AND we.recoverable = TRUE
    AND we.retry_count < 3
  ORDER BY we.created_at ASC
  LIMIT p_limit;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- ============================================================================
-- Comments for documentation
-- ============================================================================

COMMENT ON TABLE sync_runs IS 'Tracks scheduled synchronization job executions between Stripe and database';
COMMENT ON COLUMN sync_runs.job_type IS 'Type of sync job: expiration_check, webhook_recovery, or full_reconciliation';
COMMENT ON COLUMN sync_runs.metadata IS 'JSON metadata including detailed issues found and actions taken';
COMMENT ON COLUMN webhook_events.retry_count IS 'Number of times recovery has been attempted for failed webhooks';
COMMENT ON COLUMN webhook_events.recoverable IS 'Whether this event can be recovered (false if too old or permanently failed)';


-- ========================================
-- Migration: 20250302010000_fix_admin_adjust_credits.sql
-- ========================================

-- ============================================================================
-- Migration: Fix admin_adjust_credits to work with credit protection trigger
-- ============================================================================
-- The admin_adjust_credits function was created before the credit protection
-- trigger in 20250221_secure_credits.sql. It needs to set the trusted flag
-- to bypass the trigger that prevents direct credit balance updates.
-- ============================================================================

-- Update admin_adjust_credits to set the trusted operation flag
CREATE OR REPLACE FUNCTION admin_adjust_credits(
    target_user_id UUID,
    adjustment_amount INTEGER,
    adjustment_reason TEXT
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    caller_role TEXT;
    new_balance INTEGER;
BEGIN
    -- Verify caller is admin
    SELECT role INTO caller_role FROM profiles WHERE id = auth.uid();
    IF caller_role != 'admin' THEN
        RAISE EXCEPTION 'Unauthorized: Admin role required';
    END IF;

    -- Set trusted operation flag to bypass the credit protection trigger
    PERFORM set_config('app.trusted_credit_operation', 'true', true);

    -- Update credits balance
    UPDATE profiles
    SET credits_balance = credits_balance + adjustment_amount,
        updated_at = NOW()
    WHERE id = target_user_id
    RETURNING credits_balance INTO new_balance;

    IF new_balance IS NULL THEN
        RAISE EXCEPTION 'User not found: %', target_user_id;
    END IF;

    -- Log the transaction
    INSERT INTO credit_transactions (
        user_id,
        amount,
        type,
        reference_id,
        description
    ) VALUES (
        target_user_id,
        adjustment_amount,
        'bonus',
        'admin_' || auth.uid()::TEXT || '_' || NOW()::TEXT,
        adjustment_reason
    );

    RETURN new_balance;
END;
$$;

-- Ensure authenticated users can still call this function
-- (the function itself verifies admin role internally)
GRANT EXECUTE ON FUNCTION admin_adjust_credits(UUID, INTEGER, TEXT) TO authenticated;


-- ========================================
-- Migration: 20250303000000_add_credit_expiration_support.sql
-- ========================================

-- Migration: Add Credit Expiration Support
-- Description: Add support for credit expiration tracking and management
-- Date: 2025-12-03

-- ============================================
-- Step 1: Add 'expired' type to credit_transactions
-- ============================================

-- Drop existing constraint if it exists
ALTER TABLE credit_transactions
DROP CONSTRAINT IF EXISTS credit_transactions_type_check;

-- Add new constraint with 'expired' type
ALTER TABLE credit_transactions
ADD CONSTRAINT credit_transactions_type_check
CHECK (type IN ('usage', 'subscription', 'purchase', 'refund', 'bonus', 'expired'));

COMMENT ON CONSTRAINT credit_transactions_type_check ON credit_transactions IS
'Valid transaction types: usage (credit spent), subscription (monthly allocation), purchase (one-time buy), refund (credit return), bonus (promotional credit), expired (credits removed at cycle end)';

-- ============================================
-- Step 2: Create credit_expiration_events table
-- ============================================

CREATE TABLE IF NOT EXISTS credit_expiration_events (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id UUID NOT NULL REFERENCES profiles(id) ON DELETE CASCADE,
    expired_amount INTEGER NOT NULL CHECK (expired_amount >= 0),
    expiration_reason TEXT NOT NULL CHECK (expiration_reason IN ('cycle_end', 'rolling_window', 'subscription_canceled')),
    billing_cycle_end TIMESTAMPTZ,
    subscription_id TEXT,
    notes TEXT,
    created_at TIMESTAMPTZ DEFAULT NOW() NOT NULL
);

-- Add indexes for efficient querying
CREATE INDEX IF NOT EXISTS idx_credit_expiration_user ON credit_expiration_events(user_id);
CREATE INDEX IF NOT EXISTS idx_credit_expiration_date ON credit_expiration_events(created_at DESC);
CREATE INDEX IF NOT EXISTS idx_credit_expiration_reason ON credit_expiration_events(expiration_reason);

-- Add RLS policies
ALTER TABLE credit_expiration_events ENABLE ROW LEVEL SECURITY;

-- Users can view their own expiration events
CREATE POLICY "Users can view their own expiration events" ON credit_expiration_events
    FOR SELECT
    USING (auth.uid() = user_id);

-- Only service role can insert expiration events
CREATE POLICY "Only service role can insert expiration events" ON credit_expiration_events
    FOR INSERT
    WITH CHECK (auth.role() = 'service_role');

COMMENT ON TABLE credit_expiration_events IS
'Tracks credit expiration events for analytics and audit purposes. Records when credits are expired, why they were expired, and how many were removed.';

-- ============================================
-- Step 3: Create RPC function for expiring credits
-- ============================================

CREATE OR REPLACE FUNCTION expire_credits_at_cycle_end(
    target_user_id UUID,
    expiration_reason TEXT DEFAULT 'cycle_end',
    subscription_stripe_id TEXT DEFAULT NULL,
    cycle_end_date TIMESTAMPTZ DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    expired_amount INTEGER;
    transaction_description TEXT;
BEGIN
    -- Validate expiration reason
    IF expiration_reason NOT IN ('cycle_end', 'rolling_window', 'subscription_canceled') THEN
        RAISE EXCEPTION 'Invalid expiration_reason: %. Must be one of: cycle_end, rolling_window, subscription_canceled', expiration_reason;
    END IF;

    -- Get current balance (lock row for update)
    SELECT credits_balance INTO expired_amount
    FROM profiles
    WHERE id = target_user_id
    FOR UPDATE;

    -- If user not found or balance is 0 or negative, nothing to expire
    IF expired_amount IS NULL OR expired_amount <= 0 THEN
        RETURN 0;
    END IF;

    -- Reset balance to 0
    UPDATE profiles
    SET
        credits_balance = 0,
        updated_at = NOW()
    WHERE id = target_user_id;

    -- Build transaction description
    CASE expiration_reason
        WHEN 'cycle_end' THEN
            transaction_description := 'Credits expired at billing cycle end';
        WHEN 'rolling_window' THEN
            transaction_description := 'Credits expired (rolling window)';
        WHEN 'subscription_canceled' THEN
            transaction_description := 'Credits expired (subscription canceled)';
        ELSE
            transaction_description := 'Credits expired';
    END CASE;

    -- Log expiration as negative transaction
    INSERT INTO credit_transactions (
        user_id,
        amount,
        type,
        description,
        ref_id,
        created_at
    ) VALUES (
        target_user_id,
        -expired_amount,
        'expired',
        transaction_description,
        subscription_stripe_id,
        NOW()
    );

    -- Log to expiration events table
    INSERT INTO credit_expiration_events (
        user_id,
        expired_amount,
        expiration_reason,
        billing_cycle_end,
        subscription_id,
        notes,
        created_at
    ) VALUES (
        target_user_id,
        expired_amount,
        expiration_reason,
        cycle_end_date,
        subscription_stripe_id,
        transaction_description,
        NOW()
    );

    -- Raise info log for monitoring
    RAISE INFO 'Expired % credits for user % (reason: %)', expired_amount, target_user_id, expiration_reason;

    RETURN expired_amount;
END;
$$;

-- Grant execute to service_role only
REVOKE ALL ON FUNCTION expire_credits_at_cycle_end(UUID, TEXT, TEXT, TIMESTAMPTZ) FROM PUBLIC;
REVOKE ALL ON FUNCTION expire_credits_at_cycle_end(UUID, TEXT, TEXT, TIMESTAMPTZ) FROM authenticated;
GRANT EXECUTE ON FUNCTION expire_credits_at_cycle_end(UUID, TEXT, TEXT, TIMESTAMPTZ) TO service_role;

COMMENT ON FUNCTION expire_credits_at_cycle_end IS
'Expires all credits for a user and logs the expiration event. Returns the number of credits expired. Called by subscription renewal webhooks when credits should expire at cycle end.';

-- ============================================
-- Step 4: Add helper function to check if credits will expire soon
-- ============================================

CREATE OR REPLACE FUNCTION get_users_with_expiring_credits(
    days_until_expiration INTEGER DEFAULT 7
)
RETURNS TABLE (
    user_id UUID,
    email TEXT,
    credits_balance INTEGER,
    subscription_id TEXT,
    current_period_end TIMESTAMPTZ,
    days_remaining INTEGER
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
    RETURN QUERY
    SELECT
        p.id AS user_id,
        p.email,
        p.credits_balance,
        s.stripe_subscription_id AS subscription_id,
        s.current_period_end,
        EXTRACT(DAY FROM (s.current_period_end - NOW()))::INTEGER AS days_remaining
    FROM profiles p
    INNER JOIN subscriptions s ON p.id = s.user_id
    WHERE
        s.status IN ('active', 'trialing')
        AND s.current_period_end IS NOT NULL
        AND s.current_period_end > NOW()
        AND EXTRACT(DAY FROM (s.current_period_end - NOW())) <= days_until_expiration
        AND p.credits_balance > 0
    ORDER BY s.current_period_end ASC;
END;
$$;

-- Grant execute to service_role only (for scheduled jobs)
REVOKE ALL ON FUNCTION get_users_with_expiring_credits(INTEGER) FROM PUBLIC;
REVOKE ALL ON FUNCTION get_users_with_expiring_credits(INTEGER) FROM authenticated;
GRANT EXECUTE ON FUNCTION get_users_with_expiring_credits(INTEGER) TO service_role;

COMMENT ON FUNCTION get_users_with_expiring_credits IS
'Returns list of users whose credits will expire soon (within N days). Used for sending expiration warning emails via scheduled jobs.';


-- ========================================
-- Migration: 20250303010000_revoke_credit_rpc_from_authenticated.sql
-- ========================================

-- Security Fix: CRITICAL-1
-- Revoke credit modification RPC functions from authenticated role
-- These functions should only be callable by service_role (webhooks, server-side code)
--
-- Issue: authenticated users could call these functions to manipulate any user's credits
-- Fix: Only allow service_role to execute these functions

-- Revoke from authenticated role (keep service_role)
REVOKE EXECUTE ON FUNCTION public.increment_credits(UUID, INTEGER) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.increment_credits_with_log(UUID, INTEGER, TEXT, TEXT, TEXT) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.decrement_credits(UUID, INTEGER) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.decrement_credits_with_log(UUID, INTEGER, TEXT, TEXT, TEXT) FROM authenticated;
REVOKE EXECUTE ON FUNCTION public.refund_credits(UUID, INTEGER, TEXT) FROM authenticated;

-- Add validation to increment_credits_with_log to prevent negative amounts
CREATE OR REPLACE FUNCTION public.increment_credits_with_log(
  target_user_id UUID,
  amount INTEGER,
  transaction_type TEXT DEFAULT 'purchase',
  ref_id TEXT DEFAULT NULL,
  description TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  new_balance INTEGER;
BEGIN
  -- Validate amount is positive
  IF amount <= 0 THEN
    RAISE EXCEPTION 'Credit amount must be positive, got: %', amount;
  END IF;

  -- Increment credits
  UPDATE public.profiles
  SET credits_balance = credits_balance + amount
  WHERE id = target_user_id
  RETURNING credits_balance INTO new_balance;

  IF new_balance IS NULL THEN
    RAISE EXCEPTION 'User not found: %', target_user_id;
  END IF;

  -- Log transaction
  INSERT INTO public.credit_transactions (user_id, amount, type, reference_id, description)
  VALUES (target_user_id, amount, transaction_type, ref_id, description);

  RETURN new_balance;
END;
$$;

-- Re-grant to service_role only
GRANT EXECUTE ON FUNCTION public.increment_credits_with_log(UUID, INTEGER, TEXT, TEXT, TEXT) TO service_role;

-- Add validation to decrement_credits_with_log as well
CREATE OR REPLACE FUNCTION public.decrement_credits_with_log(
  target_user_id UUID,
  amount INTEGER,
  transaction_type TEXT DEFAULT 'usage',
  ref_id TEXT DEFAULT NULL,
  description TEXT DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  current_balance INTEGER;
  new_balance INTEGER;
BEGIN
  -- Validate amount is positive
  IF amount <= 0 THEN
    RAISE EXCEPTION 'Credit amount must be positive, got: %', amount;
  END IF;

  -- Lock row and check balance
  SELECT credits_balance INTO current_balance
  FROM public.profiles
  WHERE id = target_user_id
  FOR UPDATE;

  IF current_balance IS NULL THEN
    RAISE EXCEPTION 'User not found: %', target_user_id;
  END IF;

  IF current_balance < amount THEN
    RAISE EXCEPTION 'Insufficient credits. Required: %, Available: %', amount, current_balance;
  END IF;

  -- Decrement credits
  UPDATE public.profiles
  SET credits_balance = credits_balance - amount
  WHERE id = target_user_id
  RETURNING credits_balance INTO new_balance;

  -- Log transaction (negative amount for deduction)
  INSERT INTO public.credit_transactions (user_id, amount, type, reference_id, description)
  VALUES (target_user_id, -amount, transaction_type, ref_id, description);

  RETURN new_balance;
END;
$$;

-- Re-grant to service_role only
GRANT EXECUTE ON FUNCTION public.decrement_credits_with_log(UUID, INTEGER, TEXT, TEXT, TEXT) TO service_role;

-- Note: increment_credits, decrement_credits, and refund_credits are kept with service_role only
-- These are legacy functions that should not be called directly from client-side anyway


