-- Function to reset daily counters
CREATE OR REPLACE FUNCTION public.reset_daily_provider_counters()
RETURNS TRIGGER AS $$
BEGIN
  UPDATE public.provider_usage
  SET
    daily_requests = 0,
    last_daily_reset = NOW(),
    updated_at = NOW()
  WHERE date < CURRENT_DATE;

  RETURN NULL;
END;
$$ LANGUAGE plpgsql;

