  -- Get provider limits
  CASE p_provider
    WHEN 'brevo' THEN
      v_daily_limit := 300;   -- 300 free emails/day
      v_monthly_limit := 9000; -- ~300/day * 30 days
    WHEN 'resend' THEN
      v_daily_limit := 100;   -- 100 free emails/day
      v_monthly_limit := 3000; -- 3,000 free emails/month
    ELSE
      v_daily_limit := NULL;
      v_monthly_limit := NULL;
  END CASE;

  -- Check limits (only if limits are defined)
  IF v_daily_limit IS NOT NULL THEN
    IF v_current_daily_requests + p_requests > v_daily_limit THEN
      RETURN QUERY SELECT FALSE,
        v_daily_limit - v_current_daily_requests,
        v_monthly_limit - v_current_monthly_credits,
        'Daily email limit exceeded'::TEXT;
      RETURN;
    END IF;
  END IF;

  IF v_monthly_limit IS NOT NULL THEN
    IF v_current_monthly_credits + p_credits > v_monthly_limit THEN
      RETURN QUERY SELECT FALSE,
        v_daily_limit - v_current_daily_requests,
        v_monthly_limit - v_current_monthly_credits,
        'Monthly email limit exceeded'::TEXT;
      RETURN;
    END IF;
  END IF;

  -- Increment counters
  v_new_daily_requests := v_current_daily_requests + p_requests;
  v_new_monthly_credits := v_current_monthly_credits + p_credits;

  UPDATE public.email_provider_usage
  SET
    daily_requests = v_new_daily_requests,
    monthly_credits = v_new_monthly_credits,
    updated_at = NOW()
  WHERE provider = p_provider
    AND month = TO_CHAR(CURRENT_DATE, 'YYYY-MM');

  RETURN QUERY SELECT TRUE,
    v_daily_limit - v_new_daily_requests,
    v_monthly_limit - v_new_monthly_credits,
    NULL::TEXT;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Webhook events functions
CREATE OR REPLACE FUNCTION public.update_webhook_events_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SET search_path = public;

CREATE OR REPLACE FUNCTION is_webhook_event_processed(p_event_id TEXT)
RETURNS BOOLEAN AS $$
BEGIN
  RETURN EXISTS (
    SELECT 1 FROM public.webhook_events
    WHERE event_id = p_event_id
    AND status IN ('completed', 'processing')
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION mark_webhook_event_failed(p_event_id TEXT, p_error_message TEXT DEFAULT NULL)
RETURNS VOID AS $$
BEGIN
  UPDATE public.webhook_events
  SET
    status = 'failed',
    error_message = p_error_message,
    completed_at = now()
  WHERE event_id = p_event_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION mark_webhook_event_completed(p_event_id TEXT)
RETURNS VOID AS $$
BEGIN
  UPDATE public.webhook_events
  SET
    status = 'completed',
    completed_at = now()
  WHERE event_id = p_event_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

CREATE OR REPLACE FUNCTION claim_webhook_event(
  p_event_id TEXT,
  p_event_type TEXT,
  p_payload JSONB DEFAULT NULL
)
RETURNS TABLE(is_new BOOLEAN, existing_status TEXT) AS $$
DECLARE
  v_existing_status TEXT;
BEGIN
  -- First check if event exists
  SELECT we.status INTO v_existing_status
  FROM public.webhook_events we
  WHERE we.event_id = p_event_id;

  IF v_existing_status IS NOT NULL THEN
    -- Event already exists
    RETURN QUERY SELECT false, v_existing_status;
    RETURN;
  END IF;

  -- Try to insert new event
  BEGIN
    INSERT INTO public.webhook_events (event_id, event_type, status, payload)
    VALUES (p_event_id, p_event_type, 'processing', p_payload);

    RETURN QUERY SELECT true, NULL::TEXT;
  EXCEPTION WHEN unique_violation THEN
    -- Concurrent insert won - get the status of that insert
    SELECT we.status INTO v_existing_status
    FROM public.webhook_events we
    WHERE we.event_id = p_event_id;

    RETURN QUERY SELECT false, v_existing_status;
  END;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- User data function
CREATE OR REPLACE FUNCTION public.get_user_data(target_user_id UUID)
RETURNS JSON AS $$
DECLARE
  result JSON;
BEGIN
  -- Security check: Only allow users to fetch their own data
  IF target_user_id != auth.uid() THEN
    RAISE EXCEPTION 'Access denied: You can only fetch your own user data';
  END IF;

  SELECT json_build_object(
    'profile', (
      SELECT row_to_json(p.*)
      FROM public.profiles p
      WHERE p.id = target_user_id
    ),
    'subscription', (
      SELECT row_to_json(s.*)
      FROM public.subscriptions s
      WHERE s.user_id = target_user_id
        AND s.status IN ('active', 'trialing')
      ORDER BY s.created_at DESC
      LIMIT 1
    )
  ) INTO result;

  RETURN result;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- Auth trigger function
-- FIXED: Updated to use correct column names after migration 20251205_separate_credit_pools.sql
-- which renamed credits_balance to subscription_credits_balance and added purchased_credits_balance
CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  INSERT INTO public.profiles (id, subscription_credits_balance, purchased_credits_balance)
  VALUES (NEW.id, 10, 0);  -- Give new users 10 free subscription credits
  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;


-- ========================================
-- Migration: 20260120020000_fix_signup_trigger.sql
-- ========================================

-- Fix Email/Password Signup Failure
-- Date: 2026-01-20
-- Issue: Email/password signup fails with "Database error saving new user"
-- Root Causes:
--   1. handle_new_user() uses obsolete column name (credits_balance vs subscription_credits_balance)
--   2. Missing search_path in SECURITY DEFINER functions
--   3. Trigger chain may fail if one trigger fails, rolling back the entire user creation

-- ============================================
-- Fix #1: Update handle_new_user() to use correct column names
-- ============================================

-- The migration 20260120_fix_function_search_paths.sql incorrectly used credits_balance
-- which was renamed to subscription_credits_balance in migration 20251205_separate_credit_pools.sql

CREATE OR REPLACE FUNCTION public.handle_new_user()
RETURNS TRIGGER AS $$
BEGIN
  -- Insert profile with correct column names for dual-pool credit system
  INSERT INTO public.profiles (id, subscription_credits_balance, purchased_credits_balance)
  VALUES (NEW.id, 10, 0);  -- Give new users 10 free subscription credits

  -- Log the welcome bonus transaction
  -- Note: This INSERT may fail if RLS blocks it, but it won't fail user creation
  -- because we use an EXCEPTION block
  BEGIN
    INSERT INTO public.credit_transactions (user_id, amount, type, description)
    VALUES (NEW.id, 10, 'bonus', 'Welcome bonus credits');
  EXCEPTION WHEN OTHERS THEN
    -- Log the error but don't fail the user creation
    RAISE WARNING 'Failed to create welcome bonus transaction for user %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================
-- Fix #2: Update handle_new_user_email_prefs() with proper error handling
-- ============================================

CREATE OR REPLACE FUNCTION public.handle_new_user_email_prefs()
RETURNS TRIGGER AS $$
BEGIN
  -- Insert email preferences with error handling
  BEGIN
    INSERT INTO public.email_preferences (user_id)
    VALUES (NEW.id)
    ON CONFLICT (user_id) DO NOTHING;
  EXCEPTION WHEN OTHERS THEN
    -- Log the error but don't fail the user creation
    RAISE WARNING 'Failed to create email preferences for user %: %', NEW.id, SQLERRM;
  END;

  RETURN NEW;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public;

-- ============================================
-- Fix #3: Ensure RLS policies allow inserts from auth triggers
-- ============================================

-- For credit_transactions: Add explicit INSERT policy for service_role
-- This ensures that SECURITY DEFINER functions can insert during signup

DROP POLICY IF EXISTS "Service role can insert transactions" ON public.credit_transactions;

CREATE POLICY "Service role can insert transactions"
  ON public.credit_transactions
  FOR INSERT
  TO service_role
  WITH CHECK (true);

-- For email_preferences: Add explicit INSERT policy for service_role

DROP POLICY IF EXISTS "Service role can insert email preferences" ON public.email_preferences;

CREATE POLICY "Service role can insert email preferences"
  ON public.email_preferences
  FOR INSERT
  TO service_role
  WITH CHECK (true);

-- For profiles: Ensure service role can insert (should already exist, but verify)

DROP POLICY IF EXISTS "Service role can insert profiles" ON public.profiles;

CREATE POLICY "Service role can insert profiles"
  ON public.profiles
  FOR INSERT
  TO service_role
  WITH CHECK (true);

COMMENT ON FUNCTION public.handle_new_user() IS
'Trigger function that creates a user profile on signup. FIXED: Now uses correct column names (subscription_credits_balance, purchased_credits_balance) and includes error handling for transaction logging to prevent signup failures.';

COMMENT ON FUNCTION public.handle_new_user_email_prefs() IS
'Trigger function that creates email preferences on profile creation. FIXED: Added error handling and search_path to prevent signup failures.';


