-- This status is used when an article generation completes but fails quality gates

-- Drop the existing constraint
ALTER TABLE public.articles
  DROP CONSTRAINT IF EXISTS articles_status_check;

-- Recreate the constraint with the new status
ALTER TABLE public.articles
  ADD CONSTRAINT articles_status_check
  CHECK (status IN ('queued', 'generating', 'draft', 'approved', 'rejected', 'reviewed', 'published', 'failed', 'failed_quality'));

-- Add comment documenting the new status
COMMENT ON COLUMN public.articles.status IS
'Article lifecycle status: queued=waiting to start, generating=in progress, draft=ready for review, approved=awaiting publication, rejected=declined by user, reviewed=human reviewed, published=live, failed=generation error, failed_quality=completed but failed quality gates (word count, structure, etc.)';


-- ========================================
-- Migration: 20260210100000_add_keyword_normalized_and_duplicate_constraint.sql
-- ========================================

-- Add keyword_normalized column for duplicate detection
-- This enables case-insensitive duplicate checking without application-level queries

-- Add the normalized keyword column
ALTER TABLE public.articles ADD COLUMN keyword_normalized TEXT GENERATED ALWAYS AS (
  LOWER(TRIM(REGEXP_REPLACE(primary_keyword, '\s+', ' ', 'g')))
) STORED;

-- Create a partial unique index that only applies to non-failed articles
-- This allows re-generating failed articles with the same keyword
CREATE UNIQUE INDEX idx_articles_campaign_keyword_unique
  ON public.articles(campaign_id, keyword_normalized)
  WHERE status != 'failed';

-- Add index for faster duplicate lookups (includes failed articles for queries)
CREATE INDEX idx_articles_campaign_keyword_normalized
  ON public.articles(campaign_id, keyword_normalized);

-- Add comment for documentation
COMMENT ON COLUMN public.articles.keyword_normalized IS 'Auto-generated normalized keyword (lowercase, trimmed, collapsed whitespace) for duplicate detection';
COMMENT ON INDEX public.idx_articles_campaign_keyword_unique IS 'Prevents duplicate non-failed articles with same keyword within a campaign';


-- ========================================
-- Migration: 20260210110000_atomic_article_creation_with_credits.sql
-- ========================================

-- Migration: Atomic Article Creation with Credit Deduction
-- Description: Create RPC function that atomically creates article(s) and deducts credits
-- Date: 2026-02-10
--
-- This implements E7: Make queue + credit operations atomic
--
-- The function ensures that:
-- 1. Article creation and credit deduction happen in a single transaction
-- 2. If any step fails, everything rolls back
-- 3. No orphaned articles or stuck credit states can occur

-- =============================================================================
-- Function 1: Create Single Article with Credit Deduction (Atomic)
-- =============================================================================

CREATE OR REPLACE FUNCTION create_article_with_credits(
    p_user_id UUID,
    p_campaign_id UUID,
    p_project_id UUID,
    p_primary_keyword TEXT,
    p_credits_needed INTEGER DEFAULT 1,
    p_status TEXT DEFAULT 'generating',
    p_image_preset TEXT DEFAULT NULL
)
RETURNS TABLE(
    article_id UUID,
    transaction_id BIGINT,
    new_subscription_balance INTEGER,
    new_purchased_balance INTEGER,
    new_total_balance INTEGER
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    current_subscription INTEGER;
    current_purchased INTEGER;
    from_subscription INTEGER;
    from_purchased INTEGER;
    v_article_id UUID;
    v_transaction_id BIGINT;
    v_description TEXT;
BEGIN
    -- Validate amount
    IF p_credits_needed <= 0 THEN
        RAISE EXCEPTION 'Credits needed must be positive: %', p_credits_needed;
    END IF;

    -- Validate status
    IF p_status NOT IN ('queued', 'generating', 'draft', 'reviewed', 'published', 'failed') THEN
        RAISE EXCEPTION 'Invalid article status: %', p_status;
    END IF;

    -- Lock user row and get current balances (prevents race conditions)
    SELECT subscription_credits_balance, purchased_credits_balance
    INTO current_subscription, current_purchased
    FROM profiles
    WHERE id = p_user_id
    FOR UPDATE;

    IF current_subscription IS NULL THEN
        RAISE EXCEPTION 'User not found: %', p_user_id;
    END IF;

    -- Check total balance
    IF (current_subscription + current_purchased) < p_credits_needed THEN
        RAISE EXCEPTION 'Insufficient credits. Required: %, Available: %',
            p_credits_needed, (current_subscription + current_purchased);
    END IF;

    -- Calculate credit split (FIFO: subscription first, then purchased)
    from_subscription := LEAST(current_subscription, p_credits_needed);
    from_purchased := p_credits_needed - from_subscription;

    -- Create article record
    INSERT INTO articles (
        user_id,
        campaign_id,
        project_id,
        primary_keyword,
        status,
        credits_used,
        image_preset
    )
    VALUES (
        p_user_id,
        p_campaign_id,
        p_project_id,
        p_primary_keyword,
        p_status,
        p_credits_needed,
        p_image_preset
    )
    RETURNING id INTO v_article_id;

    -- Update balances atomically
    UPDATE profiles
    SET
        subscription_credits_balance = subscription_credits_balance - from_subscription,
        purchased_credits_balance = purchased_credits_balance - from_purchased
    WHERE id = p_user_id;

    -- Build description
    v_description := 'Article generation' ||
        CASE WHEN p_image_preset IS NOT NULL THEN format(' with %s image', p_image_preset) ELSE '' END ||
        CASE WHEN from_subscription > 0 AND from_purchased > 0
             THEN format(' (sub: %s, purchased: %s)', from_subscription, from_purchased)
             ELSE ''
        END;

    -- Log transaction (negative amount for consumption)
    INSERT INTO credit_transactions (user_id, amount, type, reference_id, description)
    VALUES (
        p_user_id,
        -p_credits_needed,
        'usage',
        v_article_id::TEXT,
        v_description
    )
    RETURNING id INTO v_transaction_id;

    -- Return results
    RETURN QUERY
    SELECT
        v_article_id,
        v_transaction_id,
        current_subscription - from_subscription,
        current_purchased - from_purchased,
        (current_subscription - from_subscription) + (current_purchased - from_purchased);
END;
$$;

-- Grant execute to service_role and authenticated
GRANT EXECUTE ON FUNCTION create_article_with_credits(UUID, UUID, UUID, TEXT, INTEGER, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION create_article_with_credits(UUID, UUID, UUID, TEXT, INTEGER, TEXT, TEXT) TO service_role;

COMMENT ON FUNCTION create_article_with_credits IS
'Atomically creates an article and deducts credits in a single transaction. Returns article ID, transaction ID, and updated balances. Prevents orphaned articles and partial credit states.';

-- =============================================================================
-- Function 2: Create Multiple Articles with Credit Deduction (Atomic)
-- =============================================================================

CREATE OR REPLACE FUNCTION create_articles_with_credits(
    p_user_id UUID,
    p_campaign_id UUID,
    p_project_id UUID,
    p_keywords TEXT[], -- Array of keywords
    p_credits_per_article INTEGER DEFAULT 1,
    p_status TEXT DEFAULT 'queued',
    p_image_preset TEXT DEFAULT NULL
)
RETURNS TABLE(
    article_ids UUID[],
    transaction_id BIGINT,
    total_credits_used INTEGER,
    new_subscription_balance INTEGER,
    new_purchased_balance INTEGER,
    new_total_balance INTEGER
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    current_subscription INTEGER;
    current_purchased INTEGER;
    from_subscription INTEGER;
    from_purchased INTEGER;
    v_total_credits INTEGER;
    v_article_ids UUID[];
    v_transaction_id BIGINT;
    v_description TEXT;
    v_article RECORD;
BEGIN
    -- Validate inputs
    IF p_keywords IS NULL OR array_length(p_keywords, 1) IS NULL OR array_length(p_keywords, 1) = 0 THEN
        RAISE EXCEPTION 'Keywords array cannot be empty';
    END IF;

    IF p_credits_per_article <= 0 THEN
        RAISE EXCEPTION 'Credits per article must be positive: %', p_credits_per_article;
    END IF;

    IF p_status NOT IN ('queued', 'generating', 'draft', 'reviewed', 'published', 'failed') THEN
        RAISE EXCEPTION 'Invalid article status: %', p_status;
    END IF;

    -- Calculate total credits needed
    v_total_credits := p_credits_per_article * array_length(p_keywords, 1);

    -- Lock user row and get current balances
    SELECT subscription_credits_balance, purchased_credits_balance
    INTO current_subscription, current_purchased
    FROM profiles
    WHERE id = p_user_id
    FOR UPDATE;

    IF current_subscription IS NULL THEN
        RAISE EXCEPTION 'User not found: %', p_user_id;
    END IF;

    -- Check total balance
    IF (current_subscription + current_purchased) < v_total_credits THEN
        RAISE EXCEPTION 'Insufficient credits. Required: %, Available: %',
            v_total_credits, (current_subscription + current_purchased);
    END IF;

    -- Calculate credit split
    from_subscription := LEAST(current_subscription, v_total_credits);
    from_purchased := v_total_credits - from_subscription;

    -- Create all article records in one operation
    INSERT INTO articles (
        user_id,
        campaign_id,
        project_id,
        primary_keyword,
        status,
        credits_used,
        image_preset
    )
    SELECT
        p_user_id,
        p_campaign_id,
        p_project_id,
        unnest(p_keywords),
        p_status,
        p_credits_per_article,
        p_image_preset
    RETURNING id INTO v_article_ids;

    -- Update balances atomically
    UPDATE profiles
    SET
        subscription_credits_balance = subscription_credits_balance - from_subscription,
        purchased_credits_balance = purchased_credits_balance - from_purchased
    WHERE id = p_user_id;

    -- Build description
    v_description := format('Campaign batch generation: %s articles', array_length(p_keywords, 1)) ||
        CASE WHEN p_image_preset IS NOT NULL THEN format(' with %s images', p_image_preset) ELSE '' END ||
        CASE WHEN from_subscription > 0 AND from_purchased > 0
             THEN format(' (sub: %s, purchased: %s)', from_subscription, from_purchased)
             ELSE ''
        END;

    -- Log transaction (using campaign_id as reference for batch operations)
    INSERT INTO credit_transactions (user_id, amount, type, reference_id, description)
    VALUES (
        p_user_id,
        -v_total_credits,
        'usage',
        p_campaign_id::TEXT,
        v_description
    )
    RETURNING id INTO v_transaction_id;

    -- Return results
    RETURN QUERY
    SELECT
        v_article_ids,
        v_transaction_id,
        v_total_credits,
        current_subscription - from_subscription,
        current_purchased - from_purchased,
        (current_subscription - from_subscription) + (current_purchased - from_purchased);
END;
$$;

-- Grant execute to service_role and authenticated
GRANT EXECUTE ON FUNCTION create_articles_with_credits(UUID, UUID, UUID, TEXT[], INTEGER, TEXT, TEXT) TO authenticated;
GRANT EXECUTE ON FUNCTION create_articles_with_credits(UUID, UUID, UUID, TEXT[], INTEGER, TEXT, TEXT) TO service_role;

COMMENT ON FUNCTION create_articles_with_credits IS
'Atomically creates multiple articles and deducts total credits in a single transaction. Used for campaign start. Returns article IDs array, transaction ID, total credits used, and updated balances. Prevents orphaned articles and partial credit states.';


-- ========================================
-- Migration: 20260210110100_create_integrations_tables.sql
-- ========================================

-- Create integrations system tables
-- Timestamp: 20260210110000
-- PRD: Integrations Tab - Phase 1

-- =============================================================================
-- Table: integrations
-- Stores WordPress and webhook integrations with encrypted credentials
-- =============================================================================

CREATE TABLE IF NOT EXISTS public.integrations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id UUID NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE,
  type TEXT NOT NULL CHECK (type IN ('wordpress', 'webhook')),
  name TEXT NOT NULL,
  config JSONB NOT NULL DEFAULT '{}',
  encrypted_credentials TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active', 'error', 'disabled')),
  last_tested_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for integrations
CREATE INDEX IF NOT EXISTS idx_integrations_user_id ON public.integrations(user_id);
CREATE INDEX IF NOT EXISTS idx_integrations_type ON public.integrations(type);
CREATE INDEX IF NOT EXISTS idx_integrations_status ON public.integrations(status);

-- Enable Row Level Security
ALTER TABLE public.integrations ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view their own integrations
CREATE POLICY "Users can view own integrations"
  ON public.integrations FOR SELECT
  USING (user_id = auth.uid());

-- Policy: Users can create integrations
CREATE POLICY "Users can create integrations"
  ON public.integrations FOR INSERT
  WITH CHECK (user_id = auth.uid());

-- Policy: Users can update their own integrations
CREATE POLICY "Users can update own integrations"
  ON public.integrations FOR UPDATE
  USING (user_id = auth.uid())
  WITH CHECK (user_id = auth.uid());

-- Policy: Users can delete their own integrations
CREATE POLICY "Users can delete own integrations"
  ON public.integrations FOR DELETE
  USING (user_id = auth.uid());

-- Policy: Service role has full access
CREATE POLICY "Service role has full access to integrations"
  ON public.integrations FOR ALL
  USING (auth.role() = 'service_role')
  WITH CHECK (auth.role() = 'service_role');

-- Comments
COMMENT ON TABLE public.integrations IS 'Stores WordPress and webhook integrations with encrypted credentials';
COMMENT ON COLUMN public.integrations.type IS 'Integration type: wordpress or webhook';
COMMENT ON COLUMN public.integrations.config IS 'Type-specific config (site_url, username for WP; url, secret for webhook)';
COMMENT ON COLUMN public.integrations.encrypted_credentials IS 'AES-256-GCM encrypted credentials blob';
COMMENT ON COLUMN public.integrations.status IS 'Integration status: active, error, or disabled';
COMMENT ON COLUMN public.integrations.last_tested_at IS 'Last successful connection test timestamp';

-- =============================================================================
-- Table: campaign_integrations (junction table)
-- Links campaigns to integrations (many-to-many)
-- =============================================================================

CREATE TABLE IF NOT EXISTS public.campaign_integrations (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id UUID NOT NULL REFERENCES public.campaigns(id) ON DELETE CASCADE,
  integration_id UUID NOT NULL REFERENCES public.integrations(id) ON DELETE CASCADE,
  enabled BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),

  -- Unique constraint on (campaign_id, integration_id)
  CONSTRAINT campaign_integrations_campaign_integration_unique UNIQUE (campaign_id, integration_id)
);

-- Indexes for campaign_integrations
CREATE INDEX IF NOT EXISTS idx_campaign_integrations_campaign_id ON public.campaign_integrations(campaign_id);
CREATE INDEX IF NOT EXISTS idx_campaign_integrations_integration_id ON public.campaign_integrations(integration_id);
CREATE INDEX IF NOT EXISTS idx_campaign_integrations_enabled ON public.campaign_integrations(enabled);

-- Enable Row Level Security
ALTER TABLE public.campaign_integrations ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view campaign_integrations for their own campaigns
CREATE POLICY "Users can view own campaign integrations"
  ON public.campaign_integrations FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.campaigns
      WHERE campaigns.id = campaign_integrations.campaign_id
      AND campaigns.user_id = auth.uid()
    )
  );

-- Policy: Users can create campaign_integrations for their own campaigns
CREATE POLICY "Users can create campaign integrations"
  ON public.campaign_integrations FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.campaigns
      WHERE campaigns.id = campaign_id
      AND campaigns.user_id = auth.uid()
    )
  );

-- Policy: Users can update campaign_integrations for their own campaigns
CREATE POLICY "Users can update own campaign integrations"
  ON public.campaign_integrations FOR UPDATE
  USING (
    EXISTS (
      SELECT 1 FROM public.campaigns
      WHERE campaigns.id = campaign_integrations.campaign_id
      AND campaigns.user_id = auth.uid()
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.campaigns
      WHERE campaigns.id = campaign_id
      AND campaigns.user_id = auth.uid()
    )
  );

-- Policy: Users can delete campaign_integrations for their own campaigns
CREATE POLICY "Users can delete own campaign integrations"
  ON public.campaign_integrations FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM public.campaigns
      WHERE campaigns.id = campaign_integrations.campaign_id
      AND campaigns.user_id = auth.uid()
    )
  );

-- Policy: Service role has full access
CREATE POLICY "Service role has full access to campaign_integrations"
  ON public.campaign_integrations FOR ALL
  USING (auth.role() = 'service_role')
  WITH CHECK (auth.role() = 'service_role');

-- Comments
COMMENT ON TABLE public.campaign_integrations IS 'Junction table linking campaigns to integrations';
COMMENT ON COLUMN public.campaign_integrations.enabled IS 'Can disable integration for a campaign without removing it';

-- =============================================================================
-- Table: integration_deliveries
-- Tracks delivery status of articles to integrations
-- =============================================================================

CREATE TABLE IF NOT EXISTS public.integration_deliveries (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  article_id UUID NOT NULL REFERENCES public.articles(id) ON DELETE CASCADE,
  integration_id UUID NOT NULL REFERENCES public.integrations(id) ON DELETE CASCADE,
  campaign_id UUID REFERENCES public.campaigns(id) ON DELETE SET NULL,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'delivering', 'delivered', 'failed')),
  external_id TEXT,
  external_url TEXT,
  error TEXT,
  attempt_count INTEGER NOT NULL DEFAULT 0,
  delivered_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for integration_deliveries
CREATE INDEX IF NOT EXISTS idx_integration_deliveries_article_id ON public.integration_deliveries(article_id);
CREATE INDEX IF NOT EXISTS idx_integration_deliveries_integration_id ON public.integration_deliveries(integration_id);
CREATE INDEX IF NOT EXISTS idx_integration_deliveries_campaign_id ON public.integration_deliveries(campaign_id);
CREATE INDEX IF NOT EXISTS idx_integration_deliveries_status ON public.integration_deliveries(status);

-- Composite index for querying pending deliveries
CREATE INDEX IF NOT EXISTS idx_integration_deliveries_article_status ON public.integration_deliveries(article_id, status);

-- Enable Row Level Security
ALTER TABLE public.integration_deliveries ENABLE ROW LEVEL SECURITY;

-- Policy: Users can view deliveries for their own articles
CREATE POLICY "Users can view own article deliveries"
  ON public.integration_deliveries FOR SELECT
  USING (
    EXISTS (
      SELECT 1 FROM public.articles
      WHERE articles.id = integration_deliveries.article_id
      AND articles.user_id = auth.uid()
    )
  );

-- Policy: Users can create deliveries for their own articles
CREATE POLICY "Users can create deliveries for own articles"
  ON public.integration_deliveries FOR INSERT
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.articles
      WHERE articles.id = article_id
      AND articles.user_id = auth.uid()
    )
  );

-- Policy: Users can update deliveries for their own articles
CREATE POLICY "Users can update own article deliveries"
  ON public.integration_deliveries FOR UPDATE
  USING (
    EXISTS (
      SELECT 1 FROM public.articles
      WHERE articles.id = integration_deliveries.article_id
      AND articles.user_id = auth.uid()
    )
  )
  WITH CHECK (
    EXISTS (
      SELECT 1 FROM public.articles
      WHERE articles.id = article_id
      AND articles.user_id = auth.uid()
    )
  );

-- Policy: Users can delete deliveries for their own articles
CREATE POLICY "Users can delete own article deliveries"
  ON public.integration_deliveries FOR DELETE
  USING (
    EXISTS (
      SELECT 1 FROM public.articles
      WHERE articles.id = integration_deliveries.article_id
      AND articles.user_id = auth.uid()
    )
  );

-- Policy: Service role has full access
CREATE POLICY "Service role has full access to integration_deliveries"
  ON public.integration_deliveries FOR ALL
  USING (auth.role() = 'service_role')
  WITH CHECK (auth.role() = 'service_role');

-- Comments
COMMENT ON TABLE public.integration_deliveries IS 'Tracks delivery status of articles to integrations';
COMMENT ON COLUMN public.integration_deliveries.status IS 'Delivery status: pending, delivering, delivered, or failed';
COMMENT ON COLUMN public.integration_deliveries.external_id IS 'WordPress post ID or webhook response ID';
COMMENT ON COLUMN public.integration_deliveries.external_url IS 'Published URL on WordPress';
COMMENT ON COLUMN public.integration_deliveries.error IS 'Error message if delivery failed';
COMMENT ON COLUMN public.integration_deliveries.attempt_count IS 'Number of delivery attempts';
COMMENT ON COLUMN public.integration_deliveries.delivered_at IS 'Timestamp when delivery was successful';

-- =============================================================================
-- Function to update updated_at timestamp
-- =============================================================================

CREATE OR REPLACE FUNCTION update_integrations_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

-- Trigger to auto-update updated_at
CREATE TRIGGER integrations_updated_at
  BEFORE UPDATE ON public.integrations
  FOR EACH ROW
  EXECUTE FUNCTION update_integrations_updated_at();


-- ========================================
-- Migration: 20260210200000_migrate_ai_model_to_presets.sql
-- ========================================

-- Migrate campaigns.ai_model from raw OpenRouter model IDs to preset keys
-- This supports the new centralized preset system where preset keys (budget, balanced, auto, ultra)
-- are used instead of raw model IDs (openai/gpt-4o, openrouter/auto, etc.)

-- Convert known model IDs to preset keys
UPDATE campaigns SET ai_model = 'budget' WHERE ai_model IN ('openai/gpt-4o-mini', 'google/gemini-2.0-flash');
UPDATE campaigns SET ai_model = 'balanced' WHERE ai_model = 'openai/gpt-4o';
UPDATE campaigns SET ai_model = 'auto' WHERE ai_model IN ('openrouter/auto', 'auto');
UPDATE campaigns SET ai_model = 'ultra' WHERE ai_model = 'anthropic/claude-sonnet-4-5';

-- Any remaining unknown model IDs → balanced (safe default)
UPDATE campaigns SET ai_model = 'balanced'
  WHERE ai_model NOT IN ('budget', 'balanced', 'auto', 'ultra')
    AND ai_model IS NOT NULL;

-- Also migrate articles.ai_model_used for historical records
UPDATE articles SET ai_model_used = 'budget' WHERE ai_model_used IN ('openai/gpt-4o-mini', 'google/gemini-2.0-flash');
UPDATE articles SET ai_model_used = 'balanced' WHERE ai_model_used = 'openai/gpt-4o';
UPDATE articles SET ai_model_used = 'auto' WHERE ai_model_used IN ('openrouter/auto', 'auto');
UPDATE articles SET ai_model_used = 'ultra' WHERE ai_model_used = 'anthropic/claude-sonnet-4-5';


-- ========================================
-- Migration: 20260210210100_add_keywords_normalized_constraint.sql
-- ========================================

-- Add keyword_normalized column to keywords table for case-insensitive duplicate detection
-- This enables preventing duplicate keywords regardless of case or spacing

-- Add the normalized keyword column as a stored computed column (idempotent)
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
    AND table_name = 'keywords'
    AND column_name = 'keyword_normalized'
  ) THEN
    ALTER TABLE public.keywords ADD COLUMN keyword_normalized TEXT GENERATED ALWAYS AS (
      LOWER(TRIM(REGEXP_REPLACE(keyword, '\s+', ' ', 'g')))
    ) STORED;
  END IF;
END $$;

-- Drop the old case-sensitive unique constraint on (campaign_id, keyword) if it exists
DO $$
BEGIN
  IF EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'keywords_campaign_id_keyword_key'
  ) THEN
    ALTER TABLE public.keywords DROP CONSTRAINT keywords_campaign_id_keyword_key;
  END IF;
END $$;

-- Create a new unique index on the normalized column for case-insensitive uniqueness (idempotent)
CREATE UNIQUE INDEX IF NOT EXISTS idx_keywords_campaign_normalized_unique
  ON public.keywords(campaign_id, keyword_normalized);

-- Add index for faster normalized lookups (idempotent)
CREATE INDEX IF NOT EXISTS idx_keywords_keyword_normalized
  ON public.keywords(keyword_normalized);

-- Add comments for documentation
COMMENT ON COLUMN public.keywords.keyword_normalized IS 'Auto-generated normalized keyword (lowercase, trimmed, collapsed whitespace) for case-insensitive duplicate detection';
COMMENT ON INDEX public.idx_keywords_campaign_normalized_unique IS 'Prevents duplicate keywords regardless of case or spacing within a campaign';


-- ========================================
-- Migration: 20260210210200_add_stale_article_recovery.sql
-- ========================================

-- Add stale article recovery columns
-- Tracks retry attempts and last attempt time for stuck articles

-- Add last_attempt_at column to track when generation was last attempted
ALTER TABLE public.articles
  ADD COLUMN IF NOT EXISTS last_attempt_at TIMESTAMPTZ;

-- Add attempt_count column to track retry attempts (defaults to 0)
ALTER TABLE public.articles
  ADD COLUMN IF NOT EXISTS attempt_count INTEGER NOT NULL DEFAULT 0;

-- Add comment documenting the new columns
COMMENT ON COLUMN public.articles.last_attempt_at IS
'Timestamp of the last retry attempt for stale article recovery. Used to detect stuck articles.';

COMMENT ON COLUMN public.articles.attempt_count IS
'Number of retry attempts made via stale article recovery. Max 3 before marking as failed_timeout.';

-- Add index for efficient stale article queries (status + created_at)
CREATE INDEX IF NOT EXISTS idx_articles_stale_recovery ON public.articles(status, created_at)
  WHERE status IN ('queued', 'generating');

-- Add failed_timeout status to the check constraint
-- First drop existing constraint
ALTER TABLE public.articles
  DROP CONSTRAINT IF EXISTS articles_status_check;

-- Re-add with all statuses including failed_timeout
ALTER TABLE public.articles
  ADD CONSTRAINT articles_status_check
  CHECK (status IN (
    'queued',
    'generating',
    'draft',
    'qa_checking',
    'qa_failed',
    'qa_passed',
    'approved',
    'rejected',
    'reviewed',
    'published',
    'failed',
    'failed_quality',
    'failed_timeout'
  ));

COMMENT ON COLUMN public.articles.status IS
'Article lifecycle status: queued=waiting to start, generating=in progress, draft=ready for review, qa_checking=QA in progress, qa_failed=failed QA checks, qa_passed=passed QA checks, approved=awaiting publication, rejected=declined by user, reviewed=human reviewed, published=live, failed=generation error, failed_quality=completed but failed quality gates, failed_timeout=stuck for too long and max retries exceeded';


-- ========================================
-- Migration: 20260210220100_add_campaign_generation_idempotency.sql
-- ========================================

-- Add idempotency and locking support for campaign generation start
-- This prevents duplicate article creation and double-charging on concurrent requests

-- Add generation_run_id column to campaigns table
-- This tracks the current generation run and enables idempotency
ALTER TABLE public.campaigns
  ADD COLUMN IF NOT EXISTS generation_run_id UUID;

-- Create campaign_generation_runs table for idempotency tracking
-- Similar to webhook_events but for campaign start operations
CREATE TABLE IF NOT EXISTS public.campaign_generation_runs (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  campaign_id UUID NOT NULL REFERENCES public.campaigns(id) ON DELETE CASCADE,
  idempotency_key TEXT UNIQUE NOT NULL,
  status TEXT NOT NULL DEFAULT 'processing',
    CHECK (status IN ('processing', 'completed', 'failed')),
  response_data JSONB,
  error_message TEXT,
  queued_count INTEGER NOT NULL DEFAULT 0,
  credits_used INTEGER NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  completed_at TIMESTAMPTZ,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- Indexes for performance
CREATE INDEX idx_campaign_generation_runs_campaign_id ON public.campaign_generation_runs(campaign_id);
CREATE INDEX idx_campaign_generation_runs_idempotency_key ON public.campaign_generation_runs(idempotency_key);
CREATE INDEX idx_campaign_generation_runs_status ON public.campaign_generation_runs(status);

-- RLS - Only service role should access
ALTER TABLE public.campaign_generation_runs ENABLE ROW LEVEL SECURITY;

CREATE POLICY "No direct access to campaign_generation_runs"
  ON public.campaign_generation_runs
  FOR ALL USING (false);

-- Add comment for documentation
COMMENT ON COLUMN public.campaigns.generation_run_id IS 'Current generation run ID for idempotency tracking';
COMMENT ON TABLE public.campaign_generation_runs IS 'Idempotency tracking for campaign generation start operations';

-- updated_at trigger
CREATE TRIGGER handle_campaign_generation_runs_updated_at
  BEFORE UPDATE ON public.campaign_generation_runs
  FOR EACH ROW
  EXECUTE FUNCTION handle_updated_at();

-- Function to atomically claim a campaign generation with idempotency key
-- Uses SELECT FOR UPDATE to lock the campaign row and prevent concurrent starts
CREATE OR REPLACE FUNCTION claim_campaign_generation(
  p_campaign_id UUID,
  p_idempotency_key TEXT,
  p_user_id UUID
)
RETURNS TABLE(
  success BOOLEAN,
  generation_run_id UUID,
  existing_status TEXT,
  campaign_locked BOOLEAN
) AS $$
DECLARE
  v_campaign campaigns%ROWTYPE;
  v_existing_run_id UUID;
  v_existing_status TEXT;
  v_new_run_id UUID;
BEGIN
  -- Lock the campaign row for this transaction
  -- This prevents concurrent start requests from proceeding
  SELECT * INTO v_campaign
  FROM campaigns
  WHERE id = p_campaign_id AND user_id = p_user_id
  FOR UPDATE;

  -- Check if campaign exists and user owns it
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Campaign not found or access denied' USING ERRCODE = '42501';
  END IF;

  -- Check if there's an existing run with this idempotency key
  SELECT id, status INTO v_existing_run_id, v_existing_status
  FROM campaign_generation_runs
  WHERE idempotency_key = p_idempotency_key;

  IF v_existing_run_id IS NOT NULL THEN
    -- Idempotency key already used - return cached result
    RETURN QUERY SELECT false, v_existing_run_id, v_existing_status, true::BOOLEAN;
    RETURN;
  END IF;

  -- Check if campaign is already running
  IF v_campaign.generation_run_id IS NOT NULL THEN
    -- Campaign already has an active generation run
    RETURN QUERY SELECT false, NULL::UUID, 'already_running'::TEXT, true::BOOLEAN;
    RETURN;
  END IF;

  -- Create new generation run
  v_new_run_id := gen_random_uuid();

  INSERT INTO campaign_generation_runs (
    id,
    campaign_id,
    idempotency_key,
    status
  ) VALUES (
    v_new_run_id,
    p_campaign_id,
    p_idempotency_key,
    'processing'
  );

  -- Update campaign with generation run ID
  UPDATE campaigns
  SET generation_run_id = v_new_run_id
  WHERE id = p_campaign_id;

  -- Successfully claimed
  RETURN QUERY SELECT true, v_new_run_id, NULL::TEXT, true::BOOLEAN;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to mark generation run as completed with response data
CREATE OR REPLACE FUNCTION complete_campaign_generation(
  p_generation_run_id UUID,
  p_response_data JSONB,
  p_queued_count INTEGER DEFAULT 0,
  p_credits_used INTEGER DEFAULT 0
)
RETURNS VOID AS $$
BEGIN
  UPDATE campaign_generation_runs
  SET
    status = 'completed',
    response_data = p_response_data,
    queued_count = p_queued_count,
    credits_used = p_credits_used,
    completed_at = NOW()
  WHERE id = p_generation_run_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to mark generation run as failed
CREATE OR REPLACE FUNCTION fail_campaign_generation(
  p_generation_run_id UUID,
  p_error_message TEXT
)
RETURNS VOID AS $$
BEGIN
  UPDATE campaign_generation_runs
  SET
    status = 'failed',
    error_message = p_error_message,
    completed_at = NOW()
  WHERE id = p_generation_run_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Function to clear generation_run_id from campaign (for cleanup)
CREATE OR REPLACE FUNCTION clear_campaign_generation_run(
  p_campaign_id UUID
)
RETURNS VOID AS $$
BEGIN
  UPDATE campaigns
  SET generation_run_id = NULL
  WHERE id = p_campaign_id;
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Add comments for documentation
COMMENT ON FUNCTION claim_campaign_generation IS 'Atomically claim a campaign generation with idempotency key. Uses SELECT FOR UPDATE to lock campaign row.';
COMMENT ON FUNCTION complete_campaign_generation IS 'Mark generation run as completed and store response data for idempotency';
COMMENT ON FUNCTION fail_campaign_generation IS 'Mark generation run as failed with error message';
COMMENT ON FUNCTION clear_campaign_generation_run IS 'Clear generation_run_id from campaign (typically after completion)';


