-- ============================================================
-- RPC: Get failure rate over time (hourly buckets)
-- ============================================================
CREATE OR REPLACE FUNCTION get_failure_rate_over_time(
  p_hours_ago INTEGER DEFAULT 24,
  p_user_id UUID DEFAULT NULL,
  p_project_id UUID DEFAULT NULL
)
RETURNS TABLE (
  hour TIMESTAMPTZ,
  total_articles BIGINT,
  failed_articles BIGINT,
  failure_rate NUMERIC
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT
    date_trunc('hour', created_at) AS hour,
    COUNT(*)::BIGINT AS total_articles,
    COUNT(*) FILTER (WHERE status IN ('failed', 'failed_quality'))::BIGINT AS failed_articles,
    ROUND(
      CASE
        WHEN COUNT(*) > 0 THEN (COUNT(*) FILTER (WHERE status IN ('failed', 'failed_quality'))::NUMERIC / COUNT(*) * 100)
        ELSE 0
      END,
      2
    ) AS failure_rate
  FROM articles
  WHERE created_at >= NOW() - (p_hours_ago || ' hours')::INTERVAL
    AND (p_user_id IS NULL OR user_id = p_user_id)
    AND (p_project_id IS NULL OR project_id = p_project_id)
  GROUP BY date_trunc('hour', created_at)
  ORDER BY hour DESC;
END;
$$;

-- Grant access to authenticated users
GRANT EXECUTE ON FUNCTION get_failure_rate_over_time(INTEGER, UUID, UUID) TO authenticated;

-- ============================================================
-- RPC: Get retryable failures (for recovery queue)
-- ============================================================
CREATE OR REPLACE FUNCTION get_retryable_failures(
  p_hours_ago INTEGER DEFAULT 24,
  p_limit INTEGER DEFAULT 100,
  p_user_id UUID DEFAULT NULL,
  p_project_id UUID DEFAULT NULL
)
RETURNS TABLE (
  article_id UUID,
  primary_keyword TEXT,
  failure_stage TEXT,
  provider TEXT,
  attempt_count INTEGER,
  is_retryable BOOLEAN,
  created_at TIMESTAMPTZ
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN QUERY
  SELECT
    id AS article_id,
    primary_keyword,
    failure_stage::TEXT,
    provider,
    attempt_count,
    is_retryable,
    created_at
  FROM articles
  WHERE created_at >= NOW() - (p_hours_ago || ' hours')::INTERVAL
    AND status = 'failed'
    AND is_retryable = true
    AND (p_user_id IS NULL OR user_id = p_user_id)
    AND (p_project_id IS NULL OR project_id = p_project_id)
  ORDER BY created_at DESC
  LIMIT p_limit;
END;
$$;

-- Grant access to authenticated users
GRANT EXECUTE ON FUNCTION get_retryable_failures(INTEGER, INTEGER, UUID, UUID) TO authenticated;

-- ============================================================
-- RPC: Get overall failure summary
-- ============================================================
CREATE OR REPLACE FUNCTION get_failure_summary(
  p_hours_ago INTEGER DEFAULT 24,
  p_user_id UUID DEFAULT NULL,
  p_project_id UUID DEFAULT NULL
)
RETURNS TABLE (
  total_articles BIGINT,
  total_failures BIGINT,
  retryable_failures BIGINT,
  overall_failure_rate NUMERIC,
  top_failure_stage TEXT,
  top_provider TEXT
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_total_articles BIGINT;
  v_total_failures BIGINT;
  v_retryable_failures BIGINT;
  v_top_failure_stage TEXT;
  v_top_provider TEXT;
BEGIN
  -- Get total articles in period
  SELECT COUNT(*)
  INTO v_total_articles
  FROM articles
  WHERE created_at >= NOW() - (p_hours_ago || ' hours')::INTERVAL
    AND (p_user_id IS NULL OR user_id = p_user_id)
    AND (p_project_id IS NULL OR project_id = p_project_id);

  -- Get total failures
  SELECT COUNT(*)
  INTO v_total_failures
  FROM articles
  WHERE created_at >= NOW() - (p_hours_ago || ' hours')::INTERVAL
    AND status IN ('failed', 'failed_quality')
    AND (p_user_id IS NULL OR user_id = p_user_id)
    AND (p_project_id IS NULL OR project_id = p_project_id);

  -- Get retryable failures
  SELECT COUNT(*)
  INTO v_retryable_failures
  FROM articles
  WHERE created_at >= NOW() - (p_hours_ago || ' hours')::INTERVAL
    AND status = 'failed'
    AND is_retryable = true
    AND (p_user_id IS NULL OR user_id = p_user_id)
    AND (p_project_id IS NULL OR project_id = p_project_id);

  -- Get top failure stage
  SELECT COALESCE(failure_stage::TEXT, 'unknown')
  INTO v_top_failure_stage
  FROM articles
  WHERE created_at >= NOW() - (p_hours_ago || ' hours')::INTERVAL
    AND status IN ('failed', 'failed_quality')
    AND (p_user_id IS NULL OR user_id = p_user_id)
    AND (p_project_id IS NULL OR project_id = p_project_id)
  GROUP BY failure_stage
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  -- Get top provider
  SELECT COALESCE(provider, 'unknown')
  INTO v_top_provider
  FROM articles
  WHERE created_at >= NOW() - (p_hours_ago || ' hours')::INTERVAL
    AND status IN ('failed', 'failed_quality')
    AND (p_user_id IS NULL OR user_id = p_user_id)
    AND (p_project_id IS NULL OR project_id = p_project_id)
  GROUP BY provider
  ORDER BY COUNT(*) DESC
  LIMIT 1;

  RETURN QUERY
  SELECT
    v_total_articles::BIGINT,
    v_total_failures::BIGINT,
    v_retryable_failures::BIGINT,
    ROUND(
      CASE
        WHEN v_total_articles > 0 THEN (v_total_failures::NUMERIC / v_total_articles * 100)
        ELSE 0
      END,
      2
    ),
    v_top_failure_stage,
    v_top_provider;
END;
$$;

-- Grant access to authenticated users
GRANT EXECUTE ON FUNCTION get_failure_summary(INTEGER, UUID, UUID) TO authenticated;

-- Add comments for documentation
COMMENT ON FUNCTION get_failure_metrics_by_stage IS 'Returns failure counts grouped by stage for the specified time period';
COMMENT ON FUNCTION get_failure_metrics_by_provider IS 'Returns failure counts grouped by provider for the specified time period';
COMMENT ON FUNCTION get_failure_metrics_by_model IS 'Returns failure counts grouped by AI model for the specified time period';
COMMENT ON FUNCTION get_failure_rate_over_time IS 'Returns hourly failure rate trends for the specified time period';
COMMENT ON FUNCTION get_retryable_failures IS 'Returns articles with retryable failures for recovery queue';
COMMENT ON FUNCTION get_failure_summary IS 'Returns overall failure summary including total failures, rate, and top contributors';


-- ========================================
-- Migration: 20260210240100_add_topic_fingerprint_for_semantic_dedup.sql
-- ========================================

-- Add topic_fingerprint column for semantic deduplication (E10)
-- This column stores the OpenAI embedding vector for semantic similarity detection
-- to prevent near-duplicate articles with different wording but same intent

-- Enable pgvector extension for vector operations
CREATE EXTENSION IF NOT EXISTS vector;

-- Add topic_fingerprint column to store embeddings
-- Using vector(1536) to match OpenAI text-embedding-3-small dimension
ALTER TABLE public.articles
  ADD COLUMN IF NOT EXISTS topic_fingerprint vector(1536);

-- Add index for similarity search
-- Using ivfflat for approximate nearest neighbor search on vectors
CREATE INDEX IF NOT EXISTS idx_articles_topic_fingerprint ON public.articles
  USING ivfflat (topic_fingerprint vector_cosine_ops)
  WITH (lists = 100);

-- Add similarity metadata columns
ALTER TABLE public.articles
  ADD COLUMN IF NOT EXISTS similarity_score NUMERIC CHECK (similarity_score >= 0 AND similarity_score <= 1),
  ADD COLUMN IF NOT EXISTS similar_to_article_id UUID REFERENCES public.articles(id) ON DELETE SET NULL;

-- Add comment
COMMENT ON COLUMN public.articles.topic_fingerprint IS 'Semantic embedding of article topic for near-duplicate detection using OpenAI embeddings API';
COMMENT ON COLUMN public.articles.similarity_score IS 'Cosine similarity score with the most similar existing article (0-1, higher = more similar)';
COMMENT ON COLUMN public.articles.similar_to_article_id IS 'ID of the most similar existing article that triggered a near-duplicate warning';


-- ========================================
-- Migration: 20260210240200_add_qa_pipeline.sql
-- ========================================

-- Add QA Pipeline statuses and results storage to articles table
-- This migration supports E11: Build full pre-publication QA pipeline

-- Step 1: Add new QA statuses to the articles table
ALTER TABLE public.articles
  DROP CONSTRAINT IF EXISTS articles_status_check;

-- Add the updated status check constraint with new QA statuses
ALTER TABLE public.articles
  ADD CONSTRAINT articles_status_check
  CHECK (status IN (
    'queued',
    'generating',
    'draft',
    'qa_checking',
    'qa_failed',
    'qa_passed',
    'approved',
    'rejected',
    'reviewed',
    'published',
    'failed',
    'failed_quality',
    'failed_timeout'
  ));

-- Step 2: Add QA results storage column
ALTER TABLE public.articles
  ADD COLUMN IF NOT EXISTS qa_results JSONB;

-- Step 3: Add QA configuration to projects table
ALTER TABLE public.projects
  ADD COLUMN IF NOT EXISTS qa_config JSONB DEFAULT '{"maxPlagiarismSimilarity":0.15,"minFactConsistency":0.6,"maxReadabilityGrade":12,"minReadingEase":30,"maxAILikelihood":0.8}';

-- Step 4: Add comments for documentation
COMMENT ON COLUMN public.articles.qa_results IS 'QA check results stored as JSONB with plagiarism, fact consistency, readability, and AI likelihood scores';
COMMENT ON COLUMN public.projects.qa_config IS 'QA configuration thresholds for article quality checks: { maxPlagiarismSimilarity, minFactConsistency, maxReadabilityGrade, minReadingEase, maxAILikelihood }';

-- Step 5: Create index for filtering by QA status
CREATE INDEX IF NOT EXISTS idx_articles_qa_status
  ON public.articles(status)
  WHERE status IN ('qa_checking', 'qa_failed', 'qa_passed');

-- Step 6: Create a function to check if QA is enabled for a project
CREATE OR REPLACE FUNCTION public.is_qa_enabled(p_project_id UUID)
RETURNS BOOLEAN AS $$
BEGIN
  -- QA is enabled if the project has qa_config set
  -- For now, all projects with qa_config have QA enabled
  -- This can be extended to include an enabled flag
  RETURN EXISTS (
    SELECT 1
    FROM public.projects
    WHERE id = p_project_id
    AND qa_config IS NOT NULL
  );
END;
$$ LANGUAGE plpgsql SECURITY DEFINER;

-- Step 7: Grant execute permission on the function
GRANT EXECUTE ON FUNCTION public.is_qa_enabled(UUID) TO authenticated, service_role;


-- ========================================
-- Migration: 20260211000000_fix_create_articles_with_credits_array.sql
-- ========================================

-- Migration: Fix create_articles_with_credits array collection
-- Description: Fix "malformed array literal" error when inserting multiple articles
-- Date: 2026-02-11
--
-- Bug: RETURNING id INTO v_article_ids doesn't work for multi-row INSERT.
-- PostgreSQL returns a single UUID and tries to parse it as an array literal,
-- causing "malformed array literal: <uuid>" error.
-- Fix: Use CTE with array_agg() to properly collect IDs into an array.

CREATE OR REPLACE FUNCTION create_articles_with_credits(
    p_user_id UUID,
    p_campaign_id UUID,
    p_project_id UUID,
    p_keywords TEXT[],
    p_credits_per_article INTEGER DEFAULT 1,
    p_status TEXT DEFAULT 'queued',
    p_image_preset TEXT DEFAULT NULL
)
RETURNS TABLE(
    article_ids UUID[],
    transaction_id BIGINT,
    total_credits_used INTEGER,
    new_subscription_balance INTEGER,
    new_purchased_balance INTEGER,
    new_total_balance INTEGER
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
    current_subscription INTEGER;
    current_purchased INTEGER;
    from_subscription INTEGER;
    from_purchased INTEGER;
    v_total_credits INTEGER;
    v_article_ids UUID[];
    v_transaction_id BIGINT;
    v_description TEXT;
BEGIN
    -- Validate inputs
    IF p_keywords IS NULL OR array_length(p_keywords, 1) IS NULL OR array_length(p_keywords, 1) = 0 THEN
        RAISE EXCEPTION 'Keywords array cannot be empty';
    END IF;

    IF p_credits_per_article <= 0 THEN
        RAISE EXCEPTION 'Credits per article must be positive: %', p_credits_per_article;
    END IF;

    IF p_status NOT IN ('queued', 'generating', 'draft', 'reviewed', 'published', 'failed') THEN
        RAISE EXCEPTION 'Invalid article status: %', p_status;
    END IF;

    -- Calculate total credits needed
    v_total_credits := p_credits_per_article * array_length(p_keywords, 1);

    -- Lock user row and get current balances
    SELECT subscription_credits_balance, purchased_credits_balance
    INTO current_subscription, current_purchased
    FROM profiles
    WHERE id = p_user_id
    FOR UPDATE;

    IF current_subscription IS NULL THEN
        RAISE EXCEPTION 'User not found: %', p_user_id;
    END IF;

    -- Check total balance
    IF (current_subscription + current_purchased) < v_total_credits THEN
        RAISE EXCEPTION 'Insufficient credits. Required: %, Available: %',
            v_total_credits, (current_subscription + current_purchased);
    END IF;

    -- Calculate credit split (FIFO: subscription first, then purchased)
    from_subscription := LEAST(current_subscription, v_total_credits);
    from_purchased := v_total_credits - from_subscription;

    -- Create all article records and collect IDs via CTE + array_agg
    WITH inserted AS (
        INSERT INTO articles (
            user_id,
            campaign_id,
            project_id,
            primary_keyword,
            status,
            credits_used,
            image_preset
        )
        SELECT
            p_user_id,
            p_campaign_id,
            p_project_id,
            unnest(p_keywords),
            p_status,
            p_credits_per_article,
            p_image_preset
        RETURNING id
    )
    SELECT array_agg(id) INTO v_article_ids FROM inserted;

    -- Update balances atomically
    UPDATE profiles
    SET
        subscription_credits_balance = subscription_credits_balance - from_subscription,
        purchased_credits_balance = purchased_credits_balance - from_purchased
    WHERE id = p_user_id;

    -- Build description
    v_description := format('Campaign batch generation: %s articles', array_length(p_keywords, 1)) ||
        CASE WHEN p_image_preset IS NOT NULL THEN format(' with %s images', p_image_preset) ELSE '' END ||
        CASE WHEN from_subscription > 0 AND from_purchased > 0
             THEN format(' (sub: %s, purchased: %s)', from_subscription, from_purchased)
             ELSE ''
        END;

    -- Log transaction (using campaign_id as reference for batch operations)
    INSERT INTO credit_transactions (user_id, amount, type, reference_id, description)
    VALUES (
        p_user_id,
        -v_total_credits,
        'usage',
        p_campaign_id::TEXT,
        v_description
    )
    RETURNING id INTO v_transaction_id;

    -- Return results
    RETURN QUERY
    SELECT
        v_article_ids,
        v_transaction_id,
        v_total_credits,
        current_subscription - from_subscription,
        current_purchased - from_purchased,
        (current_subscription - from_subscription) + (current_purchased - from_purchased);
END;
$$;


-- ========================================
-- Migration: 20260211000100_fix_credit_trigger_and_rpc_trust.sql
-- ========================================

-- Migration: Fix credit protection trigger + RPC trusted operation flag
-- Description: Two bugs preventing campaign start:
--   1. prevent_credit_update() trigger references old column "credits_balance"
--      (renamed to subscription_credits_balance in 20251205020000)
--   2. create_article(s)_with_credits RPCs don't set app.trusted_credit_operation,
--      so the trigger blocks their UPDATE to profiles
-- Date: 2026-02-11

-- =============================================================================
-- Fix 1: Update the trigger function to use current column names
-- =============================================================================

CREATE OR REPLACE FUNCTION public.prevent_credit_update()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  -- Check if this is a trusted internal operation (from our RPC functions)
  IF current_setting('app.trusted_credit_operation', true) = 'true' THEN
    RETURN NEW;
  END IF;

  -- Block any attempt to change credit balances for untrusted operations
  IF NEW.subscription_credits_balance IS DISTINCT FROM OLD.subscription_credits_balance THEN
    RAISE EXCEPTION 'Cannot update subscription_credits_balance directly. Use the designated API endpoints.';
  END IF;

  IF NEW.purchased_credits_balance IS DISTINCT FROM OLD.purchased_credits_balance THEN
    RAISE EXCEPTION 'Cannot update purchased_credits_balance directly. Use the designated API endpoints.';
  END IF;

  RETURN NEW;
END;
$$;

-- =============================================================================
-- Fix 2: Recreate create_article_with_credits with trusted operation flag
-- =============================================================================

CREATE OR REPLACE FUNCTION create_article_with_credits(
    p_user_id UUID,
